-- The structural tables of v0.1 (docs/domain.md): no money, so everyone in the organization reads
-- them. Generated by drizzle-kit from src/db/schema.ts, then FORCE ROW LEVEL SECURITY added by hand
-- at the end, since Drizzle does not model it (ADR 0004), and ON DELETE SET NULL ("reports_to") on
-- assignments_reports_to_fkey, since Drizzle cannot limit SET NULL to one column.
CREATE TYPE "public"."pricing_model" AS ENUM('fixed', 'time_and_materials');--> statement-breakpoint
CREATE TABLE "assignments" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"organization_id" uuid NOT NULL,
	"scenario_id" uuid NOT NULL,
	"category_id" uuid NOT NULL,
	"person_id" uuid,
	"project_role" text NOT NULL,
	"reports_to" uuid,
	"weekly_hours" numeric(5,2) NOT NULL,
	"allocation" integer NOT NULL,
	"start_date" date NOT NULL,
	"end_date" date NOT NULL,
	CONSTRAINT "assignments_organization_id_id_key" UNIQUE("organization_id","id"),
	CONSTRAINT "assignments_organization_id_scenario_id_id_key" UNIQUE("organization_id","scenario_id","id"),
	CONSTRAINT "assignments_project_role_check" CHECK ("project_role" ~ '\S' and char_length("project_role") <= 100),
	CONSTRAINT "assignments_weekly_hours_check" CHECK ("weekly_hours" > 0 and "weekly_hours" <= 168),
	CONSTRAINT "assignments_allocation_check" CHECK (allocation between 0 and 100),
	CONSTRAINT "assignments_dates_check" CHECK (end_date >= start_date),
	CONSTRAINT "assignments_reports_to_check" CHECK (reports_to <> id)
);
--> statement-breakpoint
ALTER TABLE "assignments" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
