	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"organization_id" uuid NOT NULL,
	"name" text NOT NULL,
	CONSTRAINT "categories_organization_id_id_key" UNIQUE("organization_id","id"),
	CONSTRAINT "categories_organization_id_name_key" UNIQUE("organization_id","name"),
	CONSTRAINT "categories_name_check" CHECK ("name" ~ '\S' and char_length("name") <= 100)
);
--> statement-breakpoint
ALTER TABLE "categories" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
